package ru.main.explorer;
import android.util.Size;import android.view.*;import android.graphics.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CameraLayoutTest {
 @Test public void persistedResolutionMustBeAdvertised(){Size[] sizes={new Size(4000,3000),new Size(1920,1080)};assertEquals(sizes[1],CameraActivity.preferredSize(sizes,1920,1080));assertEquals(sizes[0],CameraActivity.preferredSize(sizes,999,999));}
 @Test public void previewMatchesChosenPhotoAspect(){Size[] previews={new Size(1280,720),new Size(1440,1080)};assertEquals(previews[1],CameraActivity.choosePreview(previews,new Size(4000,3000)));assertEquals(previews[0],CameraActivity.choosePreview(previews,new Size(1920,1080)));}
 @Test public void aspectTextureUsesSensorDisplayNotViewShape(){CameraActivity.AspectTexture v=new CameraActivity.AspectTexture(RuntimeEnvironment.getApplication());for(int rotation:new int[]{0,90,180,270})for(int[] bounds:new int[][]{{800,432},{432,800}}){v.rotation=rotation;v.requestLayout();v.measure(View.MeasureSpec.makeMeasureSpec(bounds[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(bounds[1],View.MeasureSpec.EXACTLY));assertEquals(rotation%180==0?1280f/720:720f/1280,(float)v.getMeasuredWidth()/v.getMeasuredHeight(),.005);assertTrue(v.getMeasuredWidth()<=bounds[0]&&v.getMeasuredHeight()<=bounds[1]);}}
 @Test public void cameraChromeRendersInBothOrientations()throws Exception{org.robolectric.android.controller.ActivityController<CameraActivity> controller=Robolectric.buildActivity(CameraActivity.class).create();try{for(int[] size:new int[][]{{432,800},{800,432}}){CameraActivity activity=controller.get();View root=activity.findViewById(android.R.id.content);root.measure(View.MeasureSpec.makeMeasureSpec(size[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size[1],View.MeasureSpec.EXACTLY));root.layout(0,0,size[0],size[1]);Bitmap image=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));File file=new File("build/rendered/camera-019-"+size[0]+".png");file.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(file)){assertTrue(image.compress(Bitmap.CompressFormat.PNG,100,out));}}}finally{controller.destroy();}}
}
